const employees = $input.all().map(i => i.json);
const now = new Date();
const results = employees.map(emp => {
  const lastReview = emp.lastReviewDate ? new Date(emp.lastReviewDate) : null;
  const daysSinceReview = lastReview ? Math.floor((now - lastReview) / (1000 * 60 * 60 * 24)) : 999;
  const isOverdue = daysSinceReview > 100;
  const needsReview = daysSinceReview > 80;
  return {
    ...emp,
    daysSinceReview,
    isOverdue,
    needsReview,
    reviewStatus: isOverdue ? 'overdue' : needsReview ? 'due_soon' : 'current'
  };
});
return results.filter(r => r.needsReview || r.isOverdue).map(r => ({ json: r }));
